    alignItems: 'center',
  },
  buttonDisabled: {
    backgroundColor: '#c7c7cc',
  },
  buttonText: {
    color: '#fff',
    fontSize: 17,
    fontWeight: '600',
  },
  buttonTextDisabled: {
    color: '#f2f2f2',
  },
  sectionHeader: {
    fontSize: 20,
    fontWeight: '700',
    marginTop: 24,
  },
  emptyState: {
    fontSize: 15,
    color: '#8e8e93',
    marginTop: 8,
  },
  dayRow: {
    fontSize: 15,
    color: '#333',
    paddingVertical: 6,
  },
  dayRowToday: {
    fontWeight: '700',
    color: '#007AFF',
  },
});

